cat >> ledger/errors.py <<'EOF'


class UnknownFormatError(StatementError):
    """Формат выписки не распознан или не совпадает с заданным."""


class StatementRowError(StatementError):
    """Ошибка конкретной строки выписки (strict-режим); line_no обязателен."""

    def __init__(self, message: str, *, line_no: int) -> None:
        super().__init__(message, line_no=line_no)
EOF
cat > ledger/importer.py <<'EOF'
"""Импорт банковских выписок.

Поддерживаются форматы:

    nova         date,amount,description          (разделитель ",")
    sfera        Дата;Сумма;Описание              (разделитель ";")
    sfera_split  Дата;Описание;Приход;Расход      (разделитель ";")

Колонки ищутся по названию (без учёта регистра и пробелов по краям), порядок
произвольный, лишние колонки не читаются.
"""

from __future__ import annotations

import csv
import dataclasses
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass, field
from decimal import Decimal

from ledger.clock import Clock, SystemClock
from ledger.errors import (
    StatementError,
    StatementRowError,
    UnknownFormatError,
    ValidationError,
)
from ledger.models import Transaction, parse_amount
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

NOVA_COLUMNS = ("date", "amount", "description")

# формат -> (разделитель, обязательные колонки)
_FORMATS: dict[str, tuple[str, tuple[str, ...]]] = {
    "nova": (",", NOVA_COLUMNS),
    "sfera": (";", ("дата", "сумма", "описание")),
    "sfera_split": (";", ("дата", "описание", "приход", "расход")),
}

_SFERA_AMOUNT = re.compile(r"^[+-]?(\d{1,3}([   ]\d{3})+|\d+)(,\d{1,2})?$")
_SFERA_DATE = re.compile(r"^\d{2}\.\d{2}\.\d{4}$")


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError] = field(default_factory=list)


def normalize_description(text: str) -> str:
    return normalize_text(text)


def _decode(data: bytes) -> tuple[str, str]:
    try:
        return data.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return data.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise StatementError("cannot decode file as utf-8 or cp1251") from exc


def _records(text: str, delimiter: str):
    """Отдаёт (номер физической строки начала записи, поля или None, ошибка csv)."""
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)
    prev = 0
    while True:
        start = prev + 1
        try:
            row = next(reader)
        except StopIteration:
            return
        except csv.Error as exc:
            prev = reader.line_num
            yield start, None, str(exc)
            continue
        prev = reader.line_num
        yield start, row, None


def _is_garbage(row: list[str] | None) -> bool:
    return row is not None and all(not f.strip() for f in row)


def _header_index(row: list[str], fmt: str) -> dict[str, int] | None:
    names: dict[str, int] = {}
    for i, f in enumerate(row):
        names.setdefault(f.strip().casefold(), i)
    required = _FORMATS[fmt][1]
    if all(c in names for c in required):
        return {c: names[c] for c in required}
    return None


def _find_header(text: str, fmt: str):
    """Первая не мусорная запись для разделителя формата fmt."""
    for line_no, row, _err in _records(text, _FORMATS[fmt][0]):
        if not _is_garbage(row):
            return line_no, row
    return None


def detect_format(text: str) -> tuple[str, int | None]:
    """Определяет формат по заголовку; возвращает (формат, номер строки заголовка)."""
